import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/data/app.db')
SECRET = os.environ.get('APP_SECRET', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.executescript('''
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY,
            username TEXT UNIQUE,
            password_hash TEXT,
            email TEXT,
            role TEXT DEFAULT 'user',
            api_key TEXT
        );
        CREATE TABLE IF NOT EXISTS audit_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            action TEXT,
            actor TEXT,
            target TEXT,
            timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
        );
        CREATE TABLE IF NOT EXISTS sessions (
            token TEXT PRIMARY KEY,
            user_id INTEGER,
            expires_at DATETIME
        );
    ''')
    db.commit()
    db.close()

@app.before_request
def check_content_type():
    if request.method == 'POST' and request.path != '/health':
        if request.content_type != 'application/json':
            return jsonify({'error': 'unsupported media type'}), 415

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

@app.route('/api/users/lookup', methods=['POST'])
def user_lookup():
    """Internal endpoint for user lookup by various fields.
    Used by the admin dashboard for user management."""
    data = request.get_json(force=True)
    field = data.get('field', 'username')
    value = data.get('value', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role', 'api_key']
    if field not in allowed_fields:
        return jsonify({'error': 'invalid field'}), 400

    # Log the lookup attempt
    db = get_db()
    db.execute(
        "INSERT INTO audit_log (action, actor, target) VALUES (?, ?, ?)",
        ('lookup', request.remote_addr, f"{field}:{value[:50]}")
    )
    db.commit()

    # Construct and execute query - field is validated above
    query = f"SELECT id, username, email, role FROM users WHERE {field} = '{value}'"
    try:
        results = db.execute(query).fetchall()
        users = [dict(r) for r in results]
        return jsonify({'users': users, 'count': len(users)})
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/users/search', methods=['POST'])
def user_search():
    """Search users by partial username match."""
    data = request.get_json(force=True)
    term = data.get('term', '')
    limit = min(int(data.get('limit', 10)), 50)

    db = get_db()
    # Parameterized query - safe
    results = db.execute(
        "SELECT id, username, email, role FROM users WHERE username LIKE ? LIMIT ?",
        (f"%{term}%", limit)
    ).fetchall()
    return jsonify({'users': [dict(r) for r in results]})

@app.route('/api/users/verify', methods=['POST'])
def verify_api_key():
    """Verify an API key and return associated user."""
    data = request.get_json(force=True)
    key = data.get('api_key', '')

    if not key or len(key) < 16:
        return jsonify({'error': 'invalid key format'}), 400

    db = get_db()
    # Parameterized - safe
    result = db.execute(
        "SELECT id, username, role FROM users WHERE api_key = ?",
        (key,)
    ).fetchone()

    if result:
        return jsonify({'valid': True, 'user': dict(result)})
    return jsonify({'valid': False}), 401

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=os.environ.get('DEBUG', 'false') == 'true')
